def stream(self, path):
    """One pass, flat memory: handle an element at its end tag, then throw it away."""
    stack = []
    for event, elem in etree.iterparse(str(path), events=("start", "end")):
        if event == "start":
            stack.append(elem.tag); continue
        handler = self.handlers.get("/".join(stack))   # e.g. .../Positions/Position
        stack.pop()
        if handler:
            handler(elem)                               # write the row (staging)
            elem.clear()                                # free the subtree ...
            while elem.getprevious() is not None:
                del elem.getparent()[0]                 # ... and finished siblings
    self.flush()
